/* GreenBean Coffee - Base Styles */
@import url('https://fonts.googleapis.com/css2?family=DM+Sans:ital,opsz,wght@0,9..40,300;0,9..40,400;0,9..40,500;0,9..40,600;0,9..40,700;1,9..40,400&family=Inter:wght@300;400;500;600;700&display=swap');

:root {
  /* Brand Colors */
  --green-primary: #00824A;
  --green-dark: #32462F;
  --cream-warm: #F3CEA1;
  --cream-light: #FDF8F0;
  --brown-rich: #5D4037;
  --brown-light: #8D6E63;
  --white: #FFFFFF;
  --off-white: #FAFAFA;
  --text-dark: #1A1A1A;
  --text-medium: #4A4A4A;
  --text-light: #757575;
  --border-light: #E8E8E8;
  --shadow-soft: 0 4px 20px rgba(0, 0, 0, 0.08);
  --shadow-medium: 0 8px 30px rgba(0, 0, 0, 0.12);

  /* Typography */
  --font-heading: 'DM Sans', sans-serif;
  --font-body: 'Inter', sans-serif;

  /* Spacing */
  --space-xs: 0.25rem;
  --space-sm: 0.5rem;
  --space-md: 1rem;
  --space-lg: 1.5rem;
  --space-xl: 2rem;
  --space-2xl: 3rem;
  --space-3xl: 4rem;
  --space-4xl: 6rem;

  /* Border Radius */
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --radius-xl: 24px;
  --radius-full: 9999px;

  /* Transitions */
  --transition-fast: 150ms ease;
  --transition-normal: 250ms ease;
  --transition-slow: 400ms ease;
}

/* Reset */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: var(--font-body);
  font-size: 16px;
  line-height: 1.6;
  color: var(--text-dark);
  background-color: var(--white);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-heading);
  font-weight: 600;
  line-height: 1.2;
}

a {
  color: inherit;
  text-decoration: none;
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  background: none;
}

ul, ol {
  list-style: none;
}

/* Utility Classes */
.container {
  width: 100%;
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 var(--space-lg);
}

.container--narrow {
  max-width: 900px;
}

.container--wide {
  max-width: 1400px;
}

/* Button Styles */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-sm);
  padding: 0.875rem 1.75rem;
  font-size: 1rem;
  font-weight: 600;
  border-radius: var(--radius-full);
  transition: all var(--transition-normal);
  white-space: nowrap;
}

.btn--primary {
  background: var(--green-primary);
  color: var(--white);
}

.btn--primary:hover {
  background: #006B3D;
  transform: translateY(-2px);
  box-shadow: var(--shadow-medium);
}

.btn--secondary {
  background: var(--white);
  color: var(--green-primary);
  border: 2px solid var(--green-primary);
}

.btn--secondary:hover {
  background: var(--green-primary);
  color: var(--white);
}

.btn--cream {
  background: var(--cream-warm);
  color: var(--green-dark);
}

.btn--cream:hover {
  background: #E8B88A;
}

.btn--outline {
  background: transparent;
  color: var(--text-dark);
  border: 2px solid var(--border-light);
}

.btn--outline:hover {
  border-color: var(--text-dark);
}

.btn--small {
  padding: 0.5rem 1rem;
  font-size: 0.875rem;
}

.btn--large {
  padding: 1rem 2.5rem;
  font-size: 1.125rem;
}

/* Card Styles */
.card {
  background: var(--white);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-soft);
  overflow: hidden;
  transition: all var(--transition-normal);
}

.card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-medium);
}

/* Section Styles */
.section {
  padding: var(--space-4xl) 0;
}

.section--cream {
  background: var(--cream-light);
}

.section--green {
  background: var(--green-primary);
  color: var(--white);
}

.section--dark {
  background: var(--green-dark);
  color: var(--white);
}

.section__header {
  text-align: center;
  margin-bottom: var(--space-3xl);
}

.section__title {
  font-size: 2.5rem;
  margin-bottom: var(--space-md);
  color: var(--text-dark);
}

.section__subtitle {
  font-size: 1.125rem;
  color: var(--text-medium);
  max-width: 600px;
  margin: 0 auto;
}

/* Image Placeholder */
.img-placeholder {
  background: linear-gradient(135deg, var(--cream-light) 0%, var(--cream-warm) 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--brown-light);
  font-size: 0.875rem;
  text-align: center;
  padding: var(--space-lg);
}

.img-placeholder--hero {
  background: linear-gradient(135deg, var(--green-primary) 0%, var(--green-dark) 100%);
  color: rgba(255, 255, 255, 0.7);
}

/* Header/Navigation */
.header {
  position: sticky;
  top: 0;
  z-index: 1000;
  background: var(--white);
  border-bottom: 1px solid var(--border-light);
}

.header__inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--space-md) var(--space-lg);
  max-width: 1400px;
  margin: 0 auto;
}

.header__logo {
  font-family: var(--font-heading);
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--green-primary);
  display: flex;
  align-items: center;
  gap: var(--space-sm);
}

.header__nav {
  display: flex;
  align-items: center;
  gap: var(--space-xl);
}

.header__nav-link {
  font-weight: 500;
  color: var(--text-medium);
  transition: color var(--transition-fast);
  position: relative;
}

.header__nav-link:hover {
  color: var(--green-primary);
}

.header__nav-link::after {
  content: '';
  position: absolute;
  bottom: -4px;
  left: 0;
  width: 0;
  height: 2px;
  background: var(--green-primary);
  transition: width var(--transition-fast);
}

.header__nav-link:hover::after {
  width: 100%;
}

.header__actions {
  display: flex;
  align-items: center;
  gap: var(--space-md);
}

.header__account {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  font-weight: 500;
  color: var(--text-medium);
  transition: color var(--transition-fast);
}

.header__account:hover {
  color: var(--green-primary);
}

/* Mobile Navigation */
.mobile-nav-toggle {
  display: none;
  flex-direction: column;
  gap: 5px;
  padding: var(--space-sm);
}

.mobile-nav-toggle span {
  display: block;
  width: 24px;
  height: 2px;
  background: var(--text-dark);
  transition: all var(--transition-fast);
}

@media (max-width: 768px) {
  .header__nav {
    display: none;
    position: absolute;
    top: 100%;
    left: 0;
    right: 0;
    flex-direction: column;
    background: var(--white);
    padding: var(--space-lg);
    gap: var(--space-md);
    border-bottom: 1px solid var(--border-light);
  }

  .header__nav.active {
    display: flex;
  }

  .mobile-nav-toggle {
    display: flex;
  }
}

/* Footer */
.footer {
  background: var(--green-dark);
  color: var(--white);
  padding: var(--space-4xl) 0 var(--space-xl);
}

.footer__grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: var(--space-2xl);
  margin-bottom: var(--space-3xl);
}

.footer__column h4 {
  font-size: 1rem;
  font-weight: 600;
  margin-bottom: var(--space-lg);
  color: var(--cream-warm);
}

.footer__column ul {
  display: flex;
  flex-direction: column;
  gap: var(--space-sm);
}

.footer__column a {
  font-size: 0.875rem;
  color: rgba(255, 255, 255, 0.8);
  transition: color var(--transition-fast);
}

.footer__column a:hover {
  color: var(--white);
}

.footer__bottom {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-top: var(--space-xl);
  border-top: 1px solid rgba(255, 255, 255, 0.1);
}

.footer__copyright {
  font-size: 0.875rem;
  color: rgba(255, 255, 255, 0.6);
}

.footer__social {
  display: flex;
  gap: var(--space-md);
}

.footer__social a {
  color: rgba(255, 255, 255, 0.8);
  transition: color var(--transition-fast);
}

.footer__social a:hover {
  color: var(--cream-warm);
}

/* Footer Accordion (Mobile) */
.footer__accordion {
  display: none;
}

@media (max-width: 768px) {
  .footer__grid {
    grid-template-columns: 1fr;
    gap: 0;
  }

  .footer__column {
    border-bottom: 1px solid rgba(255, 255, 255, 0.1);
    padding: var(--space-md) 0;
  }

  .footer__accordion {
    display: flex;
    justify-content: space-between;
    align-items: center;
    width: 100%;
    padding: var(--space-md) 0;
    font-size: 1rem;
    font-weight: 500;
    color: var(--cream-warm);
    cursor: pointer;
  }

  .footer__accordion::after {
    content: '+';
    font-size: 1.5rem;
    transition: transform var(--transition-fast);
  }

  .footer__accordion.active::after {
    transform: rotate(45deg);
  }

  .footer__column ul {
    display: none;
    padding-bottom: var(--space-md);
  }

  .footer__column ul.active {
    display: flex;
  }

  .footer__bottom {
    flex-direction: column;
    gap: var(--space-md);
    text-align: center;
  }
}

/* Cookie Banner */
.cookie-banner {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  background: var(--white);
  padding: var(--space-lg);
  box-shadow: 0 -4px 20px rgba(0, 0, 0, 0.1);
  z-index: 1001;
  display: none;
}

.cookie-banner.active {
  display: block;
}

.cookie-banner__inner {
  max-width: 1200px;
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-xl);
}

.cookie-banner__text {
  flex: 1;
}

.cookie-banner__title {
  font-size: 1rem;
  font-weight: 600;
  margin-bottom: var(--space-xs);
}

.cookie-banner__body {
  font-size: 0.875rem;
  color: var(--text-medium);
}

.cookie-banner__actions {
  display: flex;
  gap: var(--space-md);
}

/* Carousel Styles */
.carousel {
  position: relative;
  overflow: hidden;
}

.carousel__track {
  display: flex;
  gap: var(--space-lg);
  transition: transform var(--transition-slow);
}

.carousel__item {
  flex: 0 0 calc(33.333% - var(--space-lg));
  min-width: 280px;
}

.carousel__nav {
  display: flex;
  justify-content: center;
  gap: var(--space-md);
  margin-top: var(--space-xl);
}

.carousel__btn {
  width: 48px;
  height: 48px;
  border-radius: var(--radius-full);
  background: var(--white);
  border: 2px solid var(--border-light);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all var(--transition-fast);
}

.carousel__btn:hover {
  border-color: var(--green-primary);
  color: var(--green-primary);
}

.carousel__btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

/* Tab Styles */
.tabs {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-sm);
  margin-bottom: var(--space-xl);
}

.tab {
  padding: var(--space-md) var(--space-lg);
  border-radius: var(--radius-full);
  font-weight: 500;
  background: var(--white);
  border: 2px solid var(--border-light);
  transition: all var(--transition-fast);
}

.tab:hover {
  border-color: var(--green-primary);
}

.tab.active {
  background: var(--green-primary);
  border-color: var(--green-primary);
  color: var(--white);
}

.tab__content {
  display: none;
}

.tab__content.active {
  display: block;
}

/* Form Elements */
.input {
  width: 100%;
  padding: 0.875rem 1rem;
  font-size: 1rem;
  border: 2px solid var(--border-light);
  border-radius: var(--radius-md);
  background: var(--white);
  transition: border-color var(--transition-fast);
}

.input:focus {
  outline: none;
  border-color: var(--green-primary);
}

.input::placeholder {
  color: var(--text-light);
}

/* Toggle Pills */
.toggle-pills {
  display: inline-flex;
  background: var(--off-white);
  border-radius: var(--radius-full);
  padding: 4px;
}

.toggle-pill {
  padding: 0.5rem 1.25rem;
  border-radius: var(--radius-full);
  font-weight: 500;
  transition: all var(--transition-fast);
}

.toggle-pill:hover {
  color: var(--green-primary);
}

.toggle-pill.active {
  background: var(--green-primary);
  color: var(--white);
}

/* Badge */
.badge {
  display: inline-block;
  padding: 0.25rem 0.75rem;
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  border-radius: var(--radius-full);
  background: var(--cream-warm);
  color: var(--green-dark);
}

.badge--green {
  background: var(--green-primary);
  color: var(--white);
}

/* Star Rating */
.stars {
  display: flex;
  align-items: center;
  gap: 2px;
  color: var(--cream-warm);
}

.stars--dark {
  color: var(--brown-light);
}

/* Responsive utilities */
@media (max-width: 1024px) {
  .carousel__item {
    flex: 0 0 calc(50% - var(--space-lg));
  }
}

@media (max-width: 768px) {
  .section {
    padding: var(--space-3xl) 0;
  }

  .section__title {
    font-size: 2rem;
  }

  .carousel__item {
    flex: 0 0 calc(100% - var(--space-lg));
    min-width: 100%;
  }

  .footer__grid {
    grid-template-columns: 1fr;
  }

  .cookie-banner__inner {
    flex-direction: column;
    text-align: center;
  }
}

