.header__logo {
  font-family: var(--font-heading);
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--green-primary);
  display: flex;
  align-items: center;
  gap: var(--space-sm);
}

.header__nav {
  display: flex;
  align-items: center;
  gap: var(--space-xl);
}

.header__nav-link {
  font-weight: 500;
  color: var(--text-medium);
  transition: color var(--transition-fast);
  position: relative;
