  position: absolute;
  bottom: -4px;
  left: 0;
  width: 0;
  height: 2px;
  background: var(--green-primary);
  transition: width var(--transition-fast);
}

.header__nav-link:hover::after {
  width: 100%;
}

.header__actions {
  display: flex;
  align-items: center;
  gap: var(--space-md);
}

.header__account {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  font-weight: 500;
  color: var(--text-medium);
  transition: color var(--transition-fast);
}

.header__account:hover {
  color: var(--green-primary);
}

