.footer__grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: var(--space-2xl);
  margin-bottom: var(--space-3xl);
}

.footer__column h4 {
  font-size: 1rem;
  font-weight: 600;
  margin-bottom: var(--space-lg);
  color: var(--cream-warm);
}

.footer__column ul {
  display: flex;
  flex-direction: column;
  gap: var(--space-sm);
}

.footer__column a {
  font-size: 0.875rem;
  color: rgba(255, 255, 255, 0.8);
  transition: color var(--transition-fast);
}

.footer__column a:hover {
  color: var(--white);
}

.footer__bottom {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-top: var(--space-xl);
  border-top: 1px solid rgba(255, 255, 255, 0.1);
}

.footer__copyright {
  font-size: 0.875rem;
  color: rgba(255, 255, 255, 0.6);
}

.footer__social {
  display: flex;
  gap: var(--space-md);
}

.footer__social a {
  color: rgba(255, 255, 255, 0.8);
  transition: color var(--transition-fast);
}

.footer__social a:hover {
  color: var(--cream-warm);
}

/* Footer Accordion (Mobile) */
.footer__accordion {
  display: none;
}

@media (max-width: 768px) {
  .footer__grid {
    grid-template-columns: 1fr;
    gap: 0;
  }

  .footer__column {
    border-bottom: 1px solid rgba(255, 255, 255, 0.1);
    padding: var(--space-md) 0;
  }

  .footer__accordion {
    display: flex;
    justify-content: space-between;
    align-items: center;
    width: 100%;
    padding: var(--space-md) 0;
    font-size: 1rem;
    font-weight: 500;
    color: var(--cream-warm);
    cursor: pointer;
  }

  .footer__accordion::after {
    content: '+';
    font-size: 1.5rem;
    transition: transform var(--transition-fast);
  }

  .footer__accordion.active::after {
    transform: rotate(45deg);
  }

  .footer__column ul {
    display: none;
    padding-bottom: var(--space-md);
  }

  .footer__column ul.active {
    display: flex;
  }

  .footer__bottom {
    flex-direction: column;
    gap: var(--space-md);
    text-align: center;
  }
}

/* Cookie Banner */
.cookie-banner {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  background: var(--white);
  padding: var(--space-lg);
  box-shadow: 0 -4px 20px rgba(0, 0, 0, 0.1);
  z-index: 1001;
  display: none;
}

.cookie-banner.active {
  display: block;
}

.cookie-banner__inner {
  max-width: 1200px;
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-xl);
}

.cookie-banner__text {
  flex: 1;
}

.cookie-banner__title {
  font-size: 1rem;
  font-weight: 600;
  margin-bottom: var(--space-xs);
}

.cookie-banner__body {
  font-size: 0.875rem;
  color: var(--text-medium);
}

.cookie-banner__actions {
  display: flex;
  gap: var(--space-md);
}

/* Carousel Styles */
.carousel {
  position: relative;
  overflow: hidden;
}

.carousel__track {
  display: flex;
  gap: var(--space-lg);
  transition: transform var(--transition-slow);
}

.carousel__item {
  flex: 0 0 calc(33.333% - var(--space-lg));
  min-width: 280px;
}

.carousel__nav {
  display: flex;
  justify-content: center;
  gap: var(--space-md);
  margin-top: var(--space-xl);
}

.carousel__btn {
  width: 48px;
  height: 48px;
  border-radius: var(--radius-full);
  background: var(--white);
  border: 2px solid var(--border-light);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all var(--transition-fast);
}

.carousel__btn:hover {
  border-color: var(--green-primary);
  color: var(--green-primary);
}

.carousel__btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

/* Tab Styles */
.tabs {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-sm);
  margin-bottom: var(--space-xl);
}

.tab {
  padding: var(--space-md) var(--space-lg);
  border-radius: var(--radius-full);
  font-weight: 500;
  background: var(--white);
  border: 2px solid var(--border-light);
  transition: all var(--transition-fast);
}

.tab:hover {
  border-color: var(--green-primary);
}

.tab.active {
  background: var(--green-primary);
  border-color: var(--green-primary);
  color: var(--white);
}

.tab__content {
  display: none;
}

.tab__content.active {
  display: block;
}

/* Form Elements */
.input {
  width: 100%;
  padding: 0.875rem 1rem;
  font-size: 1rem;
  border: 2px solid var(--border-light);
  border-radius: var(--radius-md);
  background: var(--white);
  transition: border-color var(--transition-fast);
}

.input:focus {
  outline: none;
  border-color: var(--green-primary);
}

.input::placeholder {
  color: var(--text-light);
}

/* Toggle Pills */
.toggle-pills {
  display: inline-flex;
  background: var(--off-white);
  border-radius: var(--radius-full);
  padding: 4px;
}

.toggle-pill {
  padding: 0.5rem 1.25rem;
  border-radius: var(--radius-full);
  font-weight: 500;
  transition: all var(--transition-fast);
}

.toggle-pill:hover {
  color: var(--green-primary);
}

.toggle-pill.active {
  background: var(--green-primary);
  color: var(--white);
}

/* Badge */
.badge {
  display: inline-block;
  padding: 0.25rem 0.75rem;
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  border-radius: var(--radius-full);
  background: var(--cream-warm);
  color: var(--green-dark);
}

.badge--green {
  background: var(--green-primary);
  color: var(--white);
}

/* Star Rating */
.stars {
  display: flex;
  align-items: center;
  gap: 2px;
  color: var(--cream-warm);
}

.stars--dark {
  color: var(--brown-light);
}

/* Responsive utilities */
@media (max-width: 1024px) {
  .carousel__item {
    flex: 0 0 calc(50% - var(--space-lg));
  }
}

@media (max-width: 768px) {
  .section {
    padding: var(--space-3xl) 0;
  }

  .section__title {
    font-size: 2rem;
  }

  .carousel__item {
    flex: 0 0 calc(100% - var(--space-lg));
    min-width: 100%;
  }

  .footer__grid {
    grid-template-columns: 1fr;
  }

  .cookie-banner__inner {
    flex-direction: column;
    text-align: center;
  }
}

