.header__nav-link::after {
  content: '';
  position: absolute;
  bottom: -4px;
  left: 0;
  width: 0;
  height: 2px;
  background: var(--green-primary);
  transition: width var(--transition-fast);
}

.header__nav-link:hover::after {
  width: 100%;
}

.header__actions {
  display: flex;
  align-items: center;
  gap: var(--space-md);
}

.header__account {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  font-weight: 500;
  color: var(--text-medium);
  transition: color var(--transition-fast);
}

.header__account:hover {
  color: var(--green-primary);
}

/* Mobile Navigation */
.mobile-nav-toggle {
  display: none;
  flex-direction: column;
  gap: 5px;
  padding: var(--space-sm);
}

.mobile-nav-toggle span {
  display: block;
  width: 24px;
  height: 2px;
  background: var(--text-dark);
  transition: all var(--transition-fast);
}

@media (max-width: 768px) {
  .header__nav {
    display: none;
    position: absolute;
    top: 100%;
    left: 0;
    right: 0;
    flex-direction: column;
    background: var(--white);
    padding: var(--space-lg);
    gap: var(--space-md);
    border-bottom: 1px solid var(--border-light);
  }

  .header__nav.active {
    display: flex;
  }

  .mobile-nav-toggle {
    display: flex;
  }
}

/* Footer */
.footer {
  background: var(--green-dark);
  color: var(--white);
  padding: var(--space-4xl) 0 var(--space-xl);
}

.footer__grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: var(--space-2xl);
  margin-bottom: var(--space-3xl);
}

.footer__column h4 {
  font-size: 1rem;
  font-weight: 600;
  margin-bottom: var(--space-lg);
  color: var(--cream-warm);
}

.footer__column ul {
  display: flex;
  flex-direction: column;
  gap: var(--space-sm);
}

.footer__column a {
  font-size: 0.875rem;
  color: rgba(255, 255, 255, 0.8);
  transition: color var(--transition-fast);
}

.footer__column a:hover {
  color: var(--white);
}

.footer__bottom {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-top: var(--space-xl);
  border-top: 1px solid rgba(255, 255, 255, 0.1);
}

.footer__copyright {
  font-size: 0.875rem;
  color: rgba(255, 255, 255, 0.6);
}

.footer__social {
  display: flex;
  gap: var(--space-md);
}

.footer__social a {
  color: rgba(255, 255, 255, 0.8);
  transition: color var(--transition-fast);
}

.footer__social a:hover {
  color: var(--cream-warm);
}

/* Footer Accordion (Mobile) */
.footer__accordion {
  display: none;
}

@media (max-width: 768px) {
  .footer__grid {
    grid-template-columns: 1fr;
    gap: 0;
  }

  .footer__column {
    border-bottom: 1px solid rgba(255, 255, 255, 0.1);
    padding: var(--space-md) 0;
  }

  .footer__accordion {
    display: flex;
    justify-content: space-between;
    align-items: center;
    width: 100%;
    padding: var(--space-md) 0;
    font-size: 1rem;
    font-weight: 500;
    color: var(--cream-warm);
    cursor: pointer;
  }

  .footer__accordion::after {
    content: '+';
    font-size: 1.5rem;
    transition: transform var(--transition-fast);
  }

  .footer__accordion.active::after {
    transform: rotate(45deg);
  }

  .footer__column ul {
    display: none;
    padding-bottom: var(--space-md);
  }

  .footer__column ul.active {
    display: flex;
  }

  .footer__bottom {
    flex-direction: column;
    gap: var(--space-md);
    text-align: center;
  }
}

/* Cookie Banner */
.cookie-banner {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  background: var(--white);
  padding: var(--space-lg);
  box-shadow: 0 -4px 20px rgba(0, 0, 0, 0.1);
  z-index: 1001;
  display: none;
}

.cookie-banner.active {
  display: block;
}

.cookie-banner__inner {
  max-width: 1200px;
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-xl);
}

.cookie-banner__text {
  flex: 1;
}

.cookie-banner__title {
  font-size: 1rem;
  font-weight: 600;
  margin-bottom: var(--space-xs);
}

.cookie-banner__body {
  font-size: 0.875rem;
  color: var(--text-medium);
}

.cookie-banner__actions {
  display: flex;
  gap: var(--space-md);
}

/* Carousel Styles */
.carousel {
  position: relative;
  overflow: hidden;
}

.carousel__track {
  display: flex;
  gap: var(--space-lg);
  transition: transform var(--transition-slow);
}

.carousel__item {
  flex: 0 0 calc(33.333% - var(--space-lg));
  min-width: 280px;
}

.carousel__nav {
  display: flex;
  justify-content: center;
  gap: var(--space-md);
  margin-top: var(--space-xl);
}

.carousel__btn {
  width: 48px;
  height: 48px;
  border-radius: var(--radius-full);
  background: var(--white);
  border: 2px solid var(--border-light);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all var(--transition-fast);
}

.carousel__btn:hover {
  border-color: var(--green-primary);
  color: var(--green-primary);
}

.carousel__btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

/* Tab Styles */
.tabs {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-sm);
  margin-bottom: var(--space-xl);
}

.tab {
  padding: var(--space-md) var(--space-lg);
  border-radius: var(--radius-full);
  font-weight: 500;
  background: var(--white);
  border: 2px solid var(--border-light);
  transition: all var(--transition-fast);
}

.tab:hover {
  border-color: var(--green-primary);
}

.tab.active {
  background: var(--green-primary);
  border-color: var(--green-primary);
  color: var(--white);
}

.tab__content {
  display: none;
}

.tab__content.active {
  display: block;
}

/* Form Elements */
.input {
  width: 100%;
  padding: 0.875rem 1rem;
  font-size: 1rem;
  border: 2px solid var(--border-light);
  border-radius: var(--radius-md);
  background: var(--white);
  transition: border-color var(--transition-fast);
}

.input:focus {
  outline: none;
  border-color: var(--green-primary);
}

.input::placeholder {
  color: var(--text-light);
}

/* Toggle Pills */
.toggle-pills {
  display: inline-flex;
  background: var(--off-white);
  border-radius: var(--radius-full);
  padding: 4px;
}

.toggle-pill {
  padding: 0.5rem 1.25rem;
  border-radius: var(--radius-full);
  font-weight: 500;
  transition: all var(--transition-fast);
}

.toggle-pill:hover {
  color: var(--green-primary);
}

.toggle-pill.active {
  background: var(--green-primary);
  color: var(--white);
}

/* Badge */
.badge {
  display: inline-block;
  padding: 0.25rem 0.75rem;
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  border-radius: var(--radius-full);
  background: var(--cream-warm);
  color: var(--green-dark);
}

.badge--green {
  background: var(--green-primary);
  color: var(--white);
}

/* Star Rating */
.stars {
  display: flex;
  align-items: center;
  gap: 2px;
  color: var(--cream-warm);
}

.stars--dark {
  color: var(--brown-light);
}

/* Responsive utilities */
@media (max-width: 1024px) {
  .carousel__item {
    flex: 0 0 calc(50% - var(--space-lg));
  }
}

@media (max-width: 768px) {
  .section {
    padding: var(--space-3xl) 0;
  }

  .section__title {
    font-size: 2rem;
  }

  .carousel__item {
    flex: 0 0 calc(100% - var(--space-lg));
    min-width: 100%;
  }

  .footer__grid {
    grid-template-columns: 1fr;
  }

  .cookie-banner__inner {
    flex-direction: column;
    text-align: center;
  }
}

arguments.content:
/* Home Page Styles */

/* Hero Section */
.hero {
  padding: var(--space-4xl) 0;
  background: linear-gradient(180deg, var(--cream-light) 0%, var(--white) 100%);
}

.hero .container {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-3xl);
  align-items: center;
}

.hero__content {
  max-width: 540px;
}

.hero__title {
  font-size: 3.5rem;
  font-weight: 700;
  color: var(--green-dark);
  margin-bottom: var(--space-lg);
  line-height: 1.1;
}

.hero__subtitle {
  font-size: 1.25rem;
  color: var(--text-medium);
  margin-bottom: var(--space-xl);
  line-height: 1.6;
}

.hero__actions {
  display: flex;
  gap: var(--space-md);
  flex-wrap: wrap;
}

@media (max-width: 768px) {
  .hero .container {
    grid-template-columns: 1fr;
    text-align: center;
  }

  .hero__content {
    max-width: 100%;
  }

  .hero__title {
    font-size: 2.5rem;
  }

  .hero__actions {
    justify-content: center;
  }
}

/* Featured Product */
.featured-product__card {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0;
  border-radius: var(--radius-xl);
}

.featured-product__image {
  height: 100%;
}

.featured-product__content {
  padding: var(--space-3xl);
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: var(--space-md);
}

.featured-product__title {
  font-size: 2rem;
  color: var(--text-dark);
}

.featured-product__body {
  font-size: 1.125rem;
  color: var(--text-medium);
  line-height: 1.6;
}

@media (max-width: 768px) {
  .featured-product__card {
    grid-template-columns: 1fr;
  }

  .featured-product__content {
    padding: var(--space-xl);
  }
}

/* Afternoon Promo */
.afternoon-promo__inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-3xl);
  align-items: center;
}

.afternoon-promo__title {
  font-size: 2.25rem;
  color: var(--green-dark);
  margin-bottom: var(--space-md);
}

.afternoon-promo__body {
  font-size: 1.125rem;
  color: var(--text-medium);
  margin-bottom: var(--space-xl);
  line-height: 1.6;
}

@media (max-width: 768px) {
  .afternoon-promo__inner {
    grid-template-columns: 1fr;
    text-align: center;
  }

  .afternoon-promo__title {
    font-size: 1.75rem;
  }
}

/* AI Recommendation */
.ai-recommendation__card {
  display: flex;
  align-items: center;
  gap: var(--space-xl);
  padding: var(--space-2xl);
  background: var(--off-white);
  border-radius: var(--radius-xl);
  border: 2px solid var(--border-light);
}

.ai-recommendation__icon {
  flex-shrink: 0;
  width: 80px;
  height: 80px;
  background: var(--cream-light);
  border-radius: var(--radius-lg);
  display: flex;
  align-items: center;
  justify-content: center;
}

.ai-recommendation__content {
  flex: 1;
}

.ai-recommendation__title {
  font-size: 1.5rem;
  color: var(--text-dark);
  margin-bottom: var(--space-sm);
}

.ai-recommendation__body {
  font-size: 1rem;
  color: var(--text-medium);
  margin-bottom: var(--space-md);
}

@media (max-width: 768px) {
  .ai-recommendation__card {
    flex-direction: column;
    text-align: center;
  }
}

/* Seasonal Highlights */
.seasonal-highlight__inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-3xl);
  align-items: center;
}

.seasonal-highlight__inner--reverse {
  direction: rtl;
}

.seasonal-highlight__inner--reverse > * {
  direction: ltr;
}

.seasonal-highlight__content {
  padding: var(--space-xl);
}

.seasonal-highlight__title {
  font-size: 2.25rem;
  margin-bottom: var(--space-md);
}

.seasonal-highlight__body {
  font-size: 1.125rem;
  opacity: 0.9;
  margin-bottom: var(--space-xl);
  line-height: 1.6;
}

.seasonal-highlight--fruity .seasonal-highlight__title {
  color: var(--white);
}

.seasonal-highlight--fruity .seasonal-highlight__body {
  color: rgba(255, 255, 255, 0.9);
}

@media (max-width: 768px) {
  .seasonal-highlight__inner {
    grid-template-columns: 1fr;
  }

  .seasonal-highlight__inner--reverse {
    direction: ltr;
  }

  .seasonal-highlight__title {
    font-size: 1.75rem;
  }
}

/* Nondairy Promo */
.nondairy-promo__card {
  display: flex;
  align-items: center;
  padding: var(--space-3xl);
  gap: var(--space-3xl);
  border-radius: var(--radius-xl);
}

.nondairy-promo__content {
  flex: 1;
}

.nondairy-promo__title {
  font-size: 2rem;
  color: var(--text-dark);
  margin-bottom: var(--space-md);
}

.nondairy-promo__body {
  font-size: 1.125rem;
  color: var(--text-medium);
  margin-bottom: var(--space-xl);
  line-height: 1.6;
}

.nondairy-promo__image {
  flex-shrink: 0;
  width: 300px;
}

@media (max-width: 768px) {
  .nondairy-promo__card {
    flex-direction: column;
    padding: var(--space-xl);
    text-align: center;
  }

  .nondairy-promo__image {
    width: 100%;
  }
}

