arguments.content:
/* Menu Page Styles */

/* Breadcrumb */
.breadcrumb {
  padding: var(--space-md) 0;
  background: var(--cream-light);
}

.breadcrumb .container {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  font-size: 0.875rem;
  color: var(--text-medium);
}

.breadcrumb a:hover {
  color: var(--green-primary);
}

.breadcrumb__sep {
  color: var(--text-light);
}

/* Menu Page Layout */
.menu-page {
  padding: var(--space-2xl) 0 var(--space-4xl);
}

.menu-page__layout {
  display: grid;
  grid-template-columns: 280px 1fr;
  gap: var(--space-3xl);
}

/* Sidebar */
.menu-sidebar {
  position: sticky;
  top: 100px;
  height: fit-content;
}

.menu-sidebar__section {
  margin-bottom: var(--space-xl);
}

.menu-sidebar__heading {
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--text-light);
  margin-bottom: var(--space-md);
}

.menu-sidebar__list {
  display: flex;
  flex-direction: column;
}

.menu-sidebar__link {
  display: block;
  padding: var(--space-sm) var(--space-md);
  font-size: 0.9375rem;
  color: var(--text-medium);
  border-radius: var(--radius-sm);
  transition: all var(--transition-fast);
}

.menu-sidebar__link:hover {
  background: var(--cream-light);
  color: var(--text-dark);
}

.menu-sidebar__link--active {
  background: var(--green-primary);
  color: var(--white);
  font-weight: 500;
}

.menu-sidebar__link--active:hover {
  background: var(--green-primary);
  color: var(--white);
}

/* Menu Content */
.menu-section {
  margin-bottom: var(--space-4xl);
}

.menu-section:last-child {
  margin-bottom: 0;
}

.menu-section__header {
  margin-bottom: var(--space-xl);
  padding-bottom: var(--space-lg);
  border-bottom: 2px solid var(--border-light);
}

.menu-section__title {
  font-size: 1.75rem;
  color: var(--text-dark);
  margin-bottom: var(--space-xs);
}

.menu-section__subtitle {
  font-size: 1rem;
  color: var(--text-light);
}

/* Menu Grid */
.menu-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-lg);
}

/* Menu Item */
.menu-item {
  cursor: pointer;
}

.menu-item__image {
  border-radius: var(--radius-md) var(--radius-md) 0 0;
  overflow: hidden;
}

.menu-item__info {
  padding: var(--space-md);
}

.menu-item__name {
  font-size: 1rem;
  font-weight: 600;
  color: var(--text-dark);
  margin-bottom: var(--space-xs);
}

.menu-item__desc {
  font-size: 0.875rem;
  color: var(--text-light);
}

/* Responsive */
@media (max-width: 1024px) {
  .menu-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 768px) {
  .menu-page__layout {
    grid-template-columns: 1fr;
  }

  .menu-sidebar {
    position: static;
    display: none;
  }

  .menu-sidebar.active {
    display: block;
  }

  .menu-grid {
    grid-template-columns: 1fr;
  }

  .menu-section__title {
    font-size: 1.5rem;
  }
}

