arguments.content:
/* Rewards Page Styles */

/* Rewards Hero */
.rewards-hero {
  padding: var(--space-4xl) 0;
  background: linear-gradient(135deg, var(--green-primary) 0%, var(--green-dark) 100%);
  color: var(--white);
  text-align: center;
}

.rewards-hero__title {
  font-size: 3rem;
  font-weight: 700;
  margin-bottom: var(--space-md);
}

.rewards-hero__subtitle {
  font-size: 1.25rem;
  opacity: 0.9;
  max-width: 600px;
  margin: 0 auto var(--space-xl);
}

.rewards-hero__actions {
  display: flex;
  justify-content: center;
  gap: var(--space-md);
  flex-wrap: wrap;
}

@media (max-width: 768px) {
  .rewards-hero__title {
    font-size: 2rem;
  }

  .rewards-hero__subtitle {
    font-size: 1rem;
  }
}

/* How It Works */
.how-it-works {
  padding-top: var(--space-4xl);
}

.steps {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-xl);
}

.step {
  text-align: center;
  padding: var(--space-2xl);
}

.step__number {
  width: 60px;
  height: 60px;
  background: var(--green-primary);
  color: var(--white);
  border-radius: var(--radius-full);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  font-weight: 700;
  margin: 0 auto var(--space-lg);
}

.step__title {
  font-size: 1.25rem;
  color: var(--text-dark);
  margin-bottom: var(--space-sm);
}

.step__desc {
  font-size: 0.9375rem;
  color: var(--text-medium);
  line-height: 1.6;
}

@media (max-width: 768px) {
  .steps {
    grid-template-columns: 1fr;
  }
}

/* Status Tiers */
.tiers {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-xl);
}

.tier {
  overflow: hidden;
}

.tier__header {
  padding: var(--space-xl);
  text-align: center;
  color: var(--white);
}

.tier__header--green {
  background: var(--green-primary);
}

.tier__header--gold {
  background: linear-gradient(135deg, #D4AF37 0%, #B8860B 100%);
}

.tier__header--reserve {
  background: linear-gradient(135deg, var(--green-dark) 0%, #1A1A1A 100%);
}

.tier__icon {
  margin-bottom: var(--space-md);
}

.tier__name {
  font-size: 1.5rem;
  font-weight: 700;
}

.tier__threshold {
  padding: var(--space-md) var(--space-xl);
  background: var(--cream-light);
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--text-medium);
  text-align: center;
}

.tier__benefits {
  padding: var(--space-xl);
}

.tier__benefits li {
  padding: var(--space-sm) 0;
  border-bottom: 1px solid var(--border-light);
  font-size: 0.9375rem;
  color: var(--text-medium);
  display: flex;
  align-items: center;
  gap: var(--space-sm);
}

.tier__benefits li:last-child {
  border-bottom: none;
}

.tier__benefits li::before {
  content: '✓';
  color: var(--green-primary);
  font-weight: 700;
}

@media (max-width: 1024px) {
  .tiers {
    grid-template-columns: 1fr;
  }
}

/* Redemption Levels */
.redemption-levels {
  background: var(--white);
}

.redemption-content {
  max-width: 600px;
  margin: 0 auto;
}

.redemption-card {
  display: flex;
  align-items: center;
  gap: var(--space-xl);
  padding: var(--space-2xl);
  background: var(--cream-light);
  border-radius: var(--radius-xl);
}

.redemption-card__icon {
  flex-shrink: 0;
  width: 80px;
  height: 80px;
  background: var(--white);
  border-radius: var(--radius-lg);
  display: flex;
  align-items: center;
  justify-content: center;
}

.redemption-card__title {
  font-size: 1.25rem;
  color: var(--text-dark);
  margin-bottom: var(--space-xs);
}

.redemption-card__desc {
  font-size: 0.9375rem;
  color: var(--text-medium);
  margin-bottom: var(--space-sm);
}

.redemption-card__value {
  display: inline-block;
  padding: 0.25rem 0.75rem;
  background: var(--green-primary);
  color: var(--white);
  font-size: 0.75rem;
  font-weight: 600;
  border-radius: var(--radius-full);
}

@media (max-width: 768px) {
  .redemption-card {
    flex-direction: column;
    text-align: center;
  }
}

/* Partnerships */
.partners {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--space-xl);
}

.partner {
  padding: var(--space-2xl);
  text-align: center;
}

.partner__logo {
  width: 80px;
  height: 80px;
  background: var(--cream-light);
  border-radius: var(--radius-lg);
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto var(--space-lg);
}

.partner__name {
  font-size: 1.25rem;
  color: var(--text-dark);
  margin-bottom: var(--space-sm);
}

.partner__desc {
  font-size: 0.9375rem;
  color: var(--text-medium);
  margin-bottom: var(--space-lg);
}

@media (max-width: 768px) {
  .partners {
    grid-template-columns: 1fr;
  }
}

/* App Download */
.app-download__card {
  display: flex;
  align-items: center;
  padding: var(--space-3xl);
  gap: var(--space-3xl);
  border-radius: var(--radius-xl);
}

.app-download__content {
  flex: 1;
}

.app-download__title {
  font-size: 1.75rem;
  color: var(--text-dark);
  margin-bottom: var(--space-md);
}

.app-download__desc {
  font-size: 1rem;
  color: var(--text-medium);
  margin-bottom: var(--space-xl);
}

.app-download__badges {
  display: flex;
  gap: var(--space-md);
}

.app-badge {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  padding: 0.75rem 1.25rem;
  background: var(--green-dark);
  color: var(--white);
  border-radius: var(--radius-md);
  font-size: 0.875rem;
  font-weight: 500;
  transition: background var(--transition-fast);
}

.app-badge:hover {
  background: var(--text-dark);
}

.app-download__image {
  flex-shrink: 0;
  width: 250px;
}

@media (max-width: 768px) {
  .app-download__card {
    flex-direction: column;
    text-align: center;
    padding: var(--space-xl);
  }

  .app-download__badges {
    justify-content: center;
  }

  .app-download__image {
    width: 100%;
  }
}

/* Terms */
.terms {
  text-align: center;
}

.terms__title {
  font-size: 1.5rem;
  color: var(--text-dark);
  margin-bottom: var(--space-md);
}

.terms__text {
  font-size: 0.9375rem;
  color: var(--text-medium);
  line-height: 1.7;
  margin-bottom: var(--space-xl);
}

