/* Gift Page Styles */

/* Gift Hero */
.gift-hero {
  padding: var(--space-4xl) 0;
  background: linear-gradient(135deg, var(--cream-warm) 0%, var(--cream-light) 100%);
  text-align: center;
}

.gift-hero__title {
  font-size: 3rem;
  font-weight: 700;
  color: var(--green-dark);
  margin-bottom: var(--space-md);
}

.gift-hero__subtitle {
  font-size: 1.25rem;
  color: var(--text-medium);
  max-width: 600px;
  margin: 0 auto var(--space-xl);
}

.gift-hero__actions {
  display: flex;
  justify-content: center;
  gap: var(--space-md);
  flex-wrap: wrap;
}

@media (max-width: 768px) {
  .gift-hero__title {
    font-size: 2rem;
  }
}

/* Featured Carousel */
.section-title {
  font-size: 1.75rem;
  color: var(--text-dark);
  margin-bottom: var(--space-xl);
}

.featured-carousel {
  overflow: hidden;
}

.featured-carousel .carousel__track {
  display: flex;
  gap: var(--space-lg);
  overflow-x: auto;
  scroll-behavior: smooth;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
}

.featured-carousel .carousel__track::-webkit-scrollbar {
  display: none;
}

/* Gift Card Preview */
.gift-card-preview {
  min-width: 280px;
}

.gift-card-preview__image {
  height: 160px;
  border-radius: var(--radius-md) var(--radius-md) 0 0;
  display: flex;
  align-items: center;
  justify-content: center;
}

.gift-card-preview__label {
  color: var(--white);
  font-size: 1.125rem;
  font-weight: 600;
  text-align: center;
  padding: var(--space-md);
  text-shadow: 0 2px 4px rgba(0, 0, 0, 0.2);
}

.gift-card-preview__info {
  padding: var(--space-md);
  text-align: center;
}

.gift-card-preview__info h3 {
  font-size: 1rem;
  color: var(--text-dark);
  margin-bottom: var(--space-sm);
}

/* Category Carousels */
.category-carousels {
  padding: var(--space-3xl) 0;
}

.category-carousel {
  margin-bottom: var(--space-3xl);
}

.category-carousel:last-child {
  margin-bottom: 0;
}

.category-carousel__title {
  font-size: 1.5rem;
  color: var(--green-dark);
  margin-bottom: var(--space-lg);
}

.category-carousel .carousel__track {
  display: flex;
  gap: var(--space-lg);
  overflow-x: auto;
  scroll-behavior: smooth;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
}

.category-carousel .carousel__track::-webkit-scrollbar {
  display: none;
}

/* Business Gifting */
.business-gifting__card {
  display: flex;
  align-items: center;
  padding: var(--space-3xl);
  gap: var(--space-3xl);
  border-radius: var(--radius-xl);
}

.business-gifting__content {
  flex: 1;
}

.business-gifting__title {
  font-size: 2rem;
  color: var(--text-dark);
  margin-bottom: var(--space-md);
}

.business-gifting__body {
  font-size: 1.125rem;
  color: var(--text-medium);
  margin-bottom: var(--space-xl);
  line-height: 1.6;
}

.business-gifting__image {
  flex-shrink: 0;
  width: 300px;
}

@media (max-width: 768px) {
  .business-gifting__card {
    flex-direction: column;
    text-align: center;
    padding: var(--space-xl);
  }

  .business-gifting__title {
    font-size: 1.5rem;
  }

  .business-gifting__image {
    width: 100%;
  }
}

/* eGift Info */
.egift-info__grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-3xl);
  align-items: start;
}

.egift-info__title {
  font-size: 1.75rem;
  color: var(--text-dark);
  margin-bottom: var(--space-md);
}

.egift-info__subtitle {
  font-size: 1.25rem;
  color: var(--text-dark);
  margin-bottom: var(--space-lg);
}

.egift-info__body {
  font-size: 1rem;
  color: var(--text-medium);
  margin-bottom: var(--space-md);
  line-height: 1.6;
}

.egift-info__actions {
  display: flex;
  gap: var(--space-md);
  margin-top: var(--space-xl);
}

.egift-info__list {
  display: flex;
  flex-direction: column;
  gap: var(--space-md);
}

.egift-info__list li {
  padding-left: var(--space-xl);
  position: relative;
  font-size: 1rem;
  color: var(--text-medium);
}

.egift-info__list li::before {
  content: '✓';
  position: absolute;
  left: 0;
  color: var(--green-primary);
  font-weight: 700;
}

@media (max-width: 768px) {
  .egift-info__grid {
    grid-template-columns: 1fr;
    text-align: center;
  }

  .egift-info__title {
    font-size: 1.5rem;
  }

  .egift-info__actions {
    justify-content: center;
  }

  .egift-info__list li {
    text-align: left;
  }
}

/* FAQ */
.faq__title {
  font-size: 1.75rem;
  color: var(--text-dark);
  margin-bottom: var(--space-xl);
  text-align: center;
}

.faq__list {
  display: flex;
  flex-direction: column;
  gap: var(--space-md);
}

.faq__item {
  border-bottom: 1px solid var(--border-light);
}

.faq__question {
  width: 100%;
  padding: var(--space-lg) 0;
  text-align: left;
  font-size: 1rem;
  font-weight: 500;
  color: var(--text-dark);
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.faq__question::after {
  content: '+';
  font-size: 1.5rem;
  transition: transform var(--transition-fast);
}

.faq__question.active::after {
  transform: rotate(45deg);
}

.faq__answer {
  display: none;
  padding-bottom: var(--space-lg);
  font-size: 0.9375rem;
  color: var(--text-medium);
  line-height: 1.6;
}

.faq__answer.active {
  display: block;
}

