arguments.content:
/* Store Locator Page Styles */

/* Search Controls */
.search-controls {
  padding: var(--space-xl) 0;
  background: var(--white);
  border-bottom: 1px solid var(--border-light);
  position: sticky;
  top: 72px;
  z-index: 100;
}

.search-controls__inner {
  display: flex;
  gap: var(--space-lg);
  align-items: center;
  flex-wrap: wrap;
}

/* Order Type Toggle */
.order-type-toggle {
  display: flex;
  gap: var(--space-sm);
}

/* Search Input */
.search-input-wrapper {
  flex: 1;
  min-width: 280px;
  position: relative;
}

.search-input-icon {
  position: absolute;
  left: var(--space-md);
  top: 50%;
  transform: translateY(-50%);
  color: var(--text-light);
}

.search-input {
  padding-left: 3rem;
}

.search-suggestions {
  position: absolute;
  top: 100%;
  left: 0;
  right: 0;
  background: var(--white);
  border: 2px solid var(--border-light);
  border-radius: var(--radius-md);
  margin-top: var(--space-xs);
  display: none;
  z-index: 10;
}

.search-suggestions.active {
  display: block;
}

.search-suggestion {
  padding: var(--space-md);
  cursor: pointer;
  transition: background var(--transition-fast);
}

.search-suggestion:hover {
  background: var(--cream-light);
}

/* Filter Button */
.filter-btn {
  white-space: nowrap;
}

.filter-btn.active {
  border-color: var(--green-primary);
  color: var(--green-primary);
}

/* Filter Panel */
.filter-panel {
  display: none;
  margin-top: var(--space-lg);
  padding: var(--space-xl);
  background: var(--cream-light);
  border-radius: var(--radius-md);
}

.filter-panel.active {
  display: block;
}

.filter-group__title {
  font-size: 1rem;
  font-weight: 600;
  color: var(--text-dark);
  margin-bottom: var(--space-md);
}

.filter-options {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-md);
}

.filter-checkbox {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  cursor: pointer;
  font-size: 0.9375rem;
  color: var(--text-medium);
}

.filter-checkbox input {
  width: 18px;
  height: 18px;
  accent-color: var(--green-primary);
}

/* Store Locator Layout */
.store-locator {
  padding: var(--space-2xl) 0 var(--space-4xl);
}

.store-locator__layout {
  display: grid;
  grid-template-columns: 1fr 400px;
  gap: var(--space-xl);
}

/* Map Container */
.map-container {
  position: sticky;
  top: 180px;
  height: calc(100vh - 220px);
}

.map-placeholder {
  height: 100%;
  background: var(--cream-light);
  border-radius: var(--radius-xl);
  position: relative;
  overflow: hidden;
  display: flex;
  align-items: center;
  justify-content: center;
}

.map-placeholder__content {
  text-align: center;
  color: var(--text-medium);
}

.map-placeholder__content h3 {
  font-size: 1.25rem;
  color: var(--text-dark);
  margin: var(--space-md) 0 var(--space-xs);
}

.map-placeholder__content p {
  font-size: 0.875rem;
}

.map-placeholder__pins {
  position: absolute;
  inset: 0;
}

.map-pin {
  position: absolute;
  transform: translate(-50%, -100%);
  animation: bounce 2s ease-in-out infinite;
}

.map-pin:nth-child(2) {
  animation-delay: 0.3s;
}

.map-pin:nth-child(3) {
  animation-delay: 0.6s;
}

.map-pin:nth-child(4) {
  animation-delay: 0.9s;
}

@keyframes bounce {
  0%, 100% {
    transform: translate(-50%, -100%);
  }
  50% {
    transform: translate(-50%, -110%);
  }
}

/* Search Results */
.search-results {
  max-height: calc(100vh - 220px);
  overflow-y: auto;
}

.search-results__header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: var(--space-lg);
}

.search-results__title {
  font-size: 1.25rem;
  color: var(--text-dark);
}

.search-results__count {
  font-size: 0.875rem;
  color: var(--text-light);
}

/* Stores List */
.stores-list {
  display: flex;
  flex-direction: column;
  gap: var(--space-md);
}

/* Store Card */
.store-card {
  padding: var(--space-lg);
}

.store-card__header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  margin-bottom: var(--space-sm);
}

.store-card__name {
  font-size: 1rem;
  font-weight: 600;
  color: var(--text-dark);
}

.store-card__distance {
  font-size: 0.875rem;
  color: var(--green-primary);
  font-weight: 500;
}

.store-card__address {
  font-size: 0.875rem;
  color: var(--text-medium);
  margin-bottom: var(--space-sm);
}

.store-card__hours {
  font-size: 0.8125rem;
  color: var(--text-light);
  margin-bottom: var(--space-md);
}

.store-card__hours-label {
  font-weight: 500;
}

.store-card__features {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-xs);
  margin-bottom: var(--space-md);
}

.store-card__features .badge {
  font-size: 0.6875rem;
  padding: 0.2rem 0.5rem;
}

.store-card__actions {
  display: flex;
  gap: var(--space-sm);
}

/* Responsive */
@media (max-width: 1024px) {
  .store-locator__layout {
    grid-template-columns: 1fr;
  }

  .map-container {
    position: static;
    height: 300px;
  }

  .search-results {
    max-height: none;
  }
}

@media (max-width: 768px) {
  .search-controls__inner {
    flex-direction: column;
    align-items: stretch;
  }

  .order-type-toggle {
    justify-content: center;
  }

  .search-input-wrapper {
    width: 100%;
  }

  .filter-btn {
    width: 100%;
    justify-content: center;
  }
}

