  top: 72px;
  z-index: 100;
}

.search-controls__inner {
  display: flex;
  gap: var(--space-lg);
  align-items: center;
  flex-wrap: wrap;
}

/* Order Type Toggle */
.order-type-toggle {
  display: flex;
  gap: var(--space-sm);
}

/* Search Input */
.search-input-wrapper {
  flex: 1;
  min-width: 280px;
  position: relative;
}

.search-input-icon {
  position: absolute;
  left: var(--space-md);
  top: 50%;
  transform: translateY(-50%);
  color: var(--text-light);
}

.search-input {
  padding-left: 3rem;
}

.search-suggestions {
  position: absolute;
  top: 100%;
  left: 0;
  right: 0;
  background: var(--white);
  border: 2px solid var(--border-light);
  border-radius: var(--radius-md);
  margin-top: var(--space-xs);
  display: none;
  z-index: 10;
}

.search-suggestions.active {
  display: block;
}

.search-suggestion {
  padding: var(--space-md);
  cursor: pointer;
  transition: background var(--transition-fast);
}

.search-suggestion:hover {
  background: var(--cream-light);
}

/* Filter Button */
.filter-btn {
  white-space: nowrap;
}

.filter-btn.active {
  border-color: var(--green-primary);
  color: var(--green-primary);
}

/* Filter Panel */
.filter-panel {
  display: none;
  margin-top: var(--space-lg);
  padding: var(--space-xl);
  background: var(--cream-light);
  border-radius: var(--radius-md);
}

.filter-panel.active {
  display: block;
}

.filter-group__title {
  font-size: 1rem;
  font-weight: 600;
  color: var(--text-dark);
  margin-bottom: var(--space-md);
}

.filter-options {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-md);
}

.filter-checkbox {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  cursor: pointer;
  font-size: 0.9375rem;
  color: var(--text-medium);
}

.filter-checkbox input {
  width: 18px;
  height: 18px;
  accent-color: var(--green-primary);
}

